solution.solution.cpp:
#include <algorithm>
#include <vector>

struct Rect { int x, y, w, h; };

static bool reachable(const Rect& win, const Rect& mon)
{
    const int overlapX{ std::min(win.x + win.w, mon.x + mon.w) - std::max(win.x, mon.x) };
    const int barTop{ win.y }, barBottom{ win.y + 32 };
    const int overlapY{ std::min(barBottom, mon.y + mon.h) - std::max(barTop, mon.y) };
    return overlapX >= 64 && overlapY > 0;
}

Rect restoreWindow(const Rect& saved, const std::vector<Rect>& monitors)
{
    if (monitors.empty()) return saved;
    for (const Rect& mon : monitors)
    {
        if (!reachable(saved, mon)) continue;
        return Rect{ saved.x, saved.y, std::min(saved.w, mon.w), std::min(saved.h, mon.h) };
    }
    const Rect& primary{ monitors.front() };
    const int w{ std::min(saved.w, primary.w) };
    const int h{ std::min(saved.h, primary.h) };
    return Rect{ primary.x + (primary.w - w) / 2, primary.y + (primary.h - h) / 2, w, h };
}

unitTests:
static bool same(const Rect& a, const Rect& b) { return a.x == b.x && a.y == b.y && a.w == b.w && a.h == b.h; }
const Rect primary{ 0, 0, 1920, 1040 }, second{ 1920, 0, 1920, 1040 };
TEST("on the second monitor, still connected") { CHECK(same(restoreWindow({ 2600, 100, 800, 600 }, { primary, second }), { 2600, 100, 800, 600 })); }
TEST("second monitor gone: centred on the primary") { CHECK(same(restoreWindow({ 2600, 100, 800, 600 }, { primary }), { 560, 220, 800, 600 })); }
TEST("too big: shrunk, position kept") { CHECK(same(restoreWindow({ 10, 10, 3000, 2000 }, { primary }), { 10, 10, 1920, 1040 })); }
TEST("title bar above the screen is not reachable") { CHECK(same(restoreWindow({ 100, -200, 400, 300 }, { primary }), { 760, 370, 400, 300 })); }
TEST("only a sliver showing is not reachable") { CHECK(same(restoreWindow({ 1900, 100, 400, 300 }, { primary }), { 760, 370, 400, 300 })); }
TEST("enough overlap is reachable") { CHECK(same(restoreWindow({ 1800, 100, 400, 300 }, { primary }), { 1800, 100, 400, 300 })); }
TEST("no monitors") { CHECK(same(restoreWindow({ 5, 6, 7, 8 }, {}), { 5, 6, 7, 8 })); }
TEST("a monitor that does not start at zero") { CHECK(same(restoreWindow({ 99999, 0, 200, 100 }, { { -1280, 0, 1280, 1000 } }), { -740, 450, 200, 100 })); }

